"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[8355],{5187:e=>{e.exports=JSON.parse('{"functions":[{"name":"Peek","desc":"Projected stack for a holder: shadowed if touched, live otherwise.","params":[{"name":"tx","desc":"","lua_type":"Transaction"},{"name":"holder","desc":"","lua_type":"ItemHolder"}],"returns":[{"desc":"","lua_type":"ItemStack?\\n"}],"function_type":"method","source":{"line":125,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/TransactionService.luau"}},{"name":"ProjectedWeight","desc":"","params":[{"name":"tx","desc":"","lua_type":"Transaction"},{"name":"inventory","desc":"","lua_type":"Inventory"}],"returns":[{"desc":"","lua_type":"number\\n"}],"function_type":"method","source":{"line":151,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/TransactionService.luau"}},{"name":"Begin","desc":"","params":[],"returns":[{"desc":"","lua_type":"Transaction\\n"}],"function_type":"method","source":{"line":212,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/TransactionService.luau"}},{"name":"Commit","desc":"Applies every shadow at once.\\n\\nRefuses when the transaction is invalid, already resolved, or when a touched\\nholder changed underneath it. Returns false without applying anything --\\npartial application is exactly what this exists to prevent.","params":[{"name":"tx","desc":"","lua_type":"Transaction"}],"returns":[{"desc":"","lua_type":"boolean"},{"desc":"","lua_type":"string?"}],"function_type":"method","source":{"line":233,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/TransactionService.luau"}},{"name":"Drop","desc":"Discards the transaction. Nothing was ever applied, so there is nothing to\\nundo -- this only releases the shadow.","params":[{"name":"tx","desc":"","lua_type":"Transaction"}],"returns":[],"function_type":"method","source":{"line":266,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/TransactionService.luau"}},{"name":"Transfer","desc":"Stage a move between two holders.\\n\\nSame conservation rule as HolderService.Transfer, applied to the shadow: the\\nremainder stays in the source\'s projected stack. Marks the transaction\\ninvalid if it could not move everything asked for, so a caller that needs\\nall-or-nothing simply checks `tx.Valid` before committing.","params":[{"name":"tx","desc":"","lua_type":"Transaction"},{"name":"from","desc":"","lua_type":"ItemHolder"},{"name":"to","desc":"","lua_type":"ItemHolder"},{"name":"quantity","desc":"","lua_type":"number?"},{"name":"group","desc":"","lua_type":"Inventory?\\n"}],"returns":[{"desc":"","lua_type":"TransferResult\\n"}],"function_type":"method","source":{"line":293,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/TransactionService.luau"}},{"name":"AddToInventory","desc":"Stage a move into the first holders of an inventory that will take it.","params":[{"name":"tx","desc":"","lua_type":"Transaction"},{"name":"from","desc":"","lua_type":"ItemHolder"},{"name":"inventory","desc":"","lua_type":"Inventory"},{"name":"quantity","desc":"","lua_type":"number?\\n"}],"returns":[{"desc":"","lua_type":"TransferResult\\n"}],"function_type":"method","source":{"line":379,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/TransactionService.luau"}},{"name":"RemoveFromInventory","desc":"Stage removal of `quantity` of an item from an inventory.\\n\\nFails the transaction if the inventory does not hold enough, so a craft\\nstages its ingredient costs and finds out before anything is consumed.","params":[{"name":"tx","desc":"","lua_type":"Transaction"},{"name":"inventory","desc":"","lua_type":"Inventory"},{"name":"class_name","desc":"","lua_type":"string"},{"name":"quantity","desc":"","lua_type":"number\\n"}],"returns":[{"desc":"","lua_type":"number\\n"}],"function_type":"method","source":{"line":437,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/TransactionService.luau"}},{"name":"ProjectedCount","desc":"Projected quantity of an item across an inventory, including nesting.","params":[{"name":"tx","desc":"","lua_type":"Transaction"},{"name":"inventory","desc":"","lua_type":"Inventory"},{"name":"class_name","desc":"","lua_type":"string\\n"}],"returns":[{"desc":"","lua_type":"number\\n"}],"function_type":"method","source":{"line":485,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/TransactionService.luau"}},{"name":"TouchedHolders","desc":"","params":[{"name":"tx","desc":"","lua_type":"Transaction"}],"returns":[{"desc":"","lua_type":"{ ItemHolder }\\n"}],"function_type":"method","source":{"line":505,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/TransactionService.luau"}}],"properties":[],"types":[],"name":"TransactionService","desc":"Staged inventory changes: build up a set of moves, then commit them all or\\nthrow them all away. Entirely optional -- the direct HolderService /\\nInventoryService calls still work and are unchanged.\\n\\nWHY\\n\\nMulti-step operations today mutate as they go, so a failure halfway leaves\\nthe inventory in a state no caller asked for: a craft that consumes three\\ningredients and cannot place the output has already eaten the ingredients,\\nand a trade that moves five stacks and stalls on the sixth has moved five.\\n\\nHOW\\n\\nA transaction keeps a copy-on-write SHADOW of every holder it touches.\\nStaged operations read and write the shadow, never the real holders, so\\nnothing is visible until Commit. Drop discards the shadow and the world is\\nuntouched -- there is no rollback step to get wrong, because nothing moved.\\n\\nVALIDITY\\n\\nEach staged operation is validated against the PROJECTED state, not the\\ncurrent one. Stage two 100-round adds into a single 100-round slot and the\\nsecond fails immediately, because by then the projection already shows the\\nslot full. So the projected state is valid at every step, and committing it\\ncannot produce a state the rules would have rejected.\\n\\nCONCURRENCY\\n\\nThe baseline quantity of every touched holder is recorded when it is first\\nshadowed. Commit re-checks it: if anything moved underneath the transaction\\n-- another commit, a direct call, a pickup on another thread -- the commit\\nis refused rather than clobbering the newer value.","source":{"line":39,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/TransactionService.luau"}}')}}]);